function CastingLadleSkimmerHookMaker.init() CastingLadleSkimmerHookMaker.ironStock=18; CastingLadleSkimmerHookMaker.bronzeStock=14; CastingLadleSkimmerHookMaker.woodStock=10; CastingLadleSkimmerHookMaker.leatherStock=8; CastingLadleSkimmerHookMaker.silverStock=8; CastingLadleSkimmerHookMaker.goldStock=6; CastingLadleSkimmerHookMaker.jewelStock=4; CastingLadleSkimmerHookMaker.pearlStock=4; CastingLadleSkimmerHookMaker.productStock={}; CastingLadleSkimmerHookMaker.buildings={}; CastingLadleSkimmerHookMaker.maker=nil; CastingLadleSkimmerHookMaker.activeMaking={}; CastingLadleSkimmerHookMaker.totalProducts=0; CastingLadleSkimmerHookMaker.dayTimer=0; print("[CastingLadleSkimmerHookMaker] Royal Casting Ladle Skimmer Hook Maker System initialized (6 products, 4 buildings)") end
function CastingLadleSkimmerHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingLadleSkimmerHookMaker.maker={name=n or ("Kljukar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljukar najet: %s (spretnost: %d)",CastingLadleSkimmerHookMaker.maker.name,s),"success") end; return true end
function CastingLadleSkimmerHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingLadleSkimmerHookMaker.build(id) local ok,e=CastingLadleSkimmerHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingLadleSkimmerHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CastingLadleSkimmerHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(CastingLadleSkimmerHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CastingLadleSkimmerHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingLadleSkimmerHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingLadleSkimmerHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingLadleSkimmerHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingLadleSkimmerHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingLadleSkimmerHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingLadleSkimmerHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingLadleSkimmerHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingLadleSkimmerHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingLadleSkimmerHookMaker.buildings==0 then return false,"Potrebna kljukna delavnica" end; if not CastingLadleSkimmerHookMaker.maker then return false,"Potreben kljukar" end; return true end
function CastingLadleSkimmerHookMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingLadleSkimmerHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingLadleSkimmerHookMaker.ironStock=CastingLadleSkimmerHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingLadleSkimmerHookMaker.bronzeStock=CastingLadleSkimmerHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingLadleSkimmerHookMaker.woodStock=CastingLadleSkimmerHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingLadleSkimmerHookMaker.leatherStock=CastingLadleSkimmerHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingLadleSkimmerHookMaker.silverStock=CastingLadleSkimmerHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingLadleSkimmerHookMaker.goldStock=CastingLadleSkimmerHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingLadleSkimmerHookMaker.jewelStock=CastingLadleSkimmerHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingLadleSkimmerHookMaker.pearlStock=CastingLadleSkimmerHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingLadleSkimmerHookMaker.maker then t=math.max(1,t-math.floor(CastingLadleSkimmerHookMaker.maker.skill/13)) end; table.insert(CastingLadleSkimmerHookMaker.activeMaking,{id="castingladleskimmerhook_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingLadleSkimmerHookMaker.completeMaking(m) local q=1.0+(CastingLadleSkimmerHookMaker.getQualityBonus()/100); if CastingLadleSkimmerHookMaker.maker then q=q+(CastingLadleSkimmerHookMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleSkimmerHookMaker.productStock[m.productType]=(CastingLadleSkimmerHookMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleSkimmerHookMaker.totalProducts=CastingLadleSkimmerHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleSkimmerHookMaker.maker then CastingLadleSkimmerHookMaker.maker.itemsMade=CastingLadleSkimmerHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleSkimmerHookMaker.maker.skill=math.min(100,CastingLadleSkimmerHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljuka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladleskimmerhook.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingLadleSkimmerHookMaker.update(dt) if not _G.state then return end; CastingLadleSkimmerHookMaker.dayTimer=CastingLadleSkimmerHookMaker.dayTimer+dt; if CastingLadleSkimmerHookMaker.dayTimer>=30 then CastingLadleSkimmerHookMaker.dayTimer=0; for i=#CastingLadleSkimmerHookMaker.activeMaking,1,-1 do local m=CastingLadleSkimmerHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingLadleSkimmerHookMaker.completeMaking(m); table.remove(CastingLadleSkimmerHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingLadleSkimmerHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingLadleSkimmerHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
